def remove_duplicate_privacy_link(apps, schema_editor):
    ContentItem = apps.get_model('site_management', 'ContentItem')
    ContentSection = apps.get_model('site_management', 'ContentSection')

    sections = ContentSection.objects.filter(area='footer')
    total_removed = 0

    for section in sections:
        duplicate_items = ContentItem.objects.filter(
            section=section,
            label='Privacy Policy',
        ).order_by('pk')
        if duplicate_items.count() > 1:
            keep_item = duplicate_items.filter(url__startswith='/privacy-policy/').first() or duplicate_items.first()
            duplicates = [item for item in duplicate_items if item.pk != (keep_item.pk if keep_item else item.pk)]
            for item in duplicates:
                item.delete()
                total_removed += 1

    print(f'Removed {total_removed} duplicate Privacy Policy footer items')


